/**
 * FR-30.21 (D-5): the icon font holds the icons the app uses, and no other.
 *
 * `@mdi/font` carries 7 461 icons (395 KB of the sign-in page's 843 KB); the source names about 300. This collects the
 * names (`mdi-…`) the UI sources use, the ones Vuetify's own components use (`vuetify/lib/iconsets/mdi`), and the
 * allow-list below, and writes, into `packages/ui-shared/src/styles/icons/`:
 *   - `mdi-subset.woff2`: the font with those glyphs only;
 *   - `mdi-subset.css`: its `@font-face`, the `.mdi` base rule, one rule per icon, and the font's helper classes;
 *   - `icons.json`: the names, which `unit/icon-subset.test.ts` holds the sources to.
 * The templates keep their string names. A name used and not shipped fails that test: run this, and commit the three.
 *
 * Usage: bun scripts/build-icon-subset.ts [--check]   (--check: exit 1 when the committed subset is not what the
 * sources use, and write nothing)
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

const ROOT = join(import.meta.dir, '..')
export const ICON_DIR = join(ROOT, 'packages', 'ui-shared', 'src', 'styles', 'icons')
const UI_SHARED = join(ROOT, 'packages', 'ui-shared')

/**
 * Names that exist only in data, never in a source file (none today). A name built at runtime from parts would go
 * here: the collector reads source text.
 */
export const ALLOW_LIST: string[] = []

/** Helper classes of the font, not icons. */
const HELPERS = /^mdi-(set|\d+px|light|dark|inactive|rotate-\d+|flip-[hv]|spin)$/

const NAME = /\bmdi-[a-z0-9]+(?:-[a-z0-9]+)*/g

/** The UI's sources: every package's `src`, and the web app's shell. Tests, built output and the generated CSS excluded. */
function sourceFiles(): string[] {
  const out: string[] = []
  const walk = (dir: string) => {
    for (const name of readdirSync(dir)) {
      if (name === 'node_modules' || name === 'dist' || name === 'icons') continue
      const path = join(dir, name)
      if (statSync(path).isDirectory()) walk(path)
      else if (/\.(vue|ts|json|html)$/.test(name)) out.push(path)
    }
  }
  const packages = join(ROOT, 'packages')
  for (const pkg of readdirSync(packages)) {
    if (pkg === 'tests' || pkg === 'e2e') continue
    const src = join(packages, pkg, 'src')
    if (existsSync(src)) walk(src)
  }
  out.push(join(packages, 'web', 'index.html'))
  return out
}

/** Every icon name the app uses: the sources', Vuetify's own, the allow-list. Sorted, helpers left out. */
export function usedIconNames(): string[] {
  const names = new Set<string>(ALLOW_LIST)
  for (const file of sourceFiles()) for (const m of readFileSync(file, 'utf8').matchAll(NAME)) names.add(m[0])
  const vuetifyMdi = Bun.resolveSync('vuetify/lib/iconsets/mdi.js', UI_SHARED)
  for (const m of readFileSync(vuetifyMdi, 'utf8').matchAll(NAME)) names.add(m[0])
  return [...names].filter((n) => !HELPERS.test(n)).sort()
}

/** The font's own stylesheet: each icon's codepoint, and the helper rules after the last icon. */
export function mdiFont(): { css: string; codepoints: Map<string, string>; helpers: string; woff2: string } {
  const cssPath = Bun.resolveSync('@mdi/font/css/materialdesignicons.css', UI_SHARED)
  const css = readFileSync(cssPath, 'utf8')
  const codepoints = new Map<string, string>()
  let lastEnd = 0
  for (const m of css.matchAll(/\.(mdi-[a-z0-9-]+)::before \{\s*content: "\\([0-9A-F]+)";\s*\}/g)) {
    codepoints.set(m[1]!, m[2]!)
    lastEnd = m.index! + m[0].length
  }
  return { css, codepoints, helpers: css.slice(lastEnd).replace(/\/\*# sourceMappingURL=.*\*\//, '').trim(), woff2: join(dirname(cssPath), '..', 'fonts', 'materialdesignicons-webfont.woff2') }
}

function subsetCss(names: string[], codepoints: Map<string, string>, helpers: string): string {
  const rules = names.map((n) => `.${n}::before {\n  content: "\\${codepoints.get(n)}";\n}`).join('\n\n')
  return `/* Generated by scripts/build-icon-subset.ts (FR-30.21): the Material Design Icons the app uses. Do not edit. */
@font-face {
  font-family: "Material Design Icons";
  src: url("./mdi-subset.woff2") format("woff2");
  font-weight: normal;
  font-style: normal;
  font-display: block;
}

.mdi:before,
.mdi-set {
  display: inline-block;
  font: normal normal normal 24px/1 "Material Design Icons";
  font-size: inherit;
  text-rendering: auto;
  line-height: inherit;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

${rules}

${helpers}
`
}

async function main() {
  const check = process.argv.includes('--check')
  const names = usedIconNames()
  const font = mdiFont()
  const unknown = names.filter((n) => !font.codepoints.has(n))
  if (unknown.length) {
    console.error(`✗ used, and not in @mdi/font: ${unknown.join(', ')}`)
    process.exit(1)
  }
  const listed = JSON.stringify(names, null, 2) + '\n'
  if (check) {
    const committed = existsSync(join(ICON_DIR, 'icons.json')) ? readFileSync(join(ICON_DIR, 'icons.json'), 'utf8') : ''
    if (committed.replace(/\r\n/g, '\n') !== listed) {
      console.error('✗ the icon subset is not what the sources use: run `bun scripts/build-icon-subset.ts` and commit it')
      process.exit(1)
    }
    console.log(`✓ ${names.length} icons, as committed`)
    return
  }
  const subsetFont = (await import('subset-font')).default
  const text = names.map((n) => String.fromCodePoint(parseInt(font.codepoints.get(n)!, 16))).join('')
  const woff2 = await subsetFont(readFileSync(font.woff2), text, { targetFormat: 'woff2' })
  writeFileSync(join(ICON_DIR, 'mdi-subset.woff2'), woff2)
  writeFileSync(join(ICON_DIR, 'mdi-subset.css'), subsetCss(names, font.codepoints, font.helpers))
  writeFileSync(join(ICON_DIR, 'icons.json'), listed)
  console.log(`icon subset: ${names.length} of ${font.codepoints.size} icons, ${(woff2.length / 1024).toFixed(1)} KB woff2 (the whole font ${(statSync(font.woff2).size / 1024).toFixed(1)} KB)`)
}

if (import.meta.main) await main()
